mapper.select:
SELECT * FROM ( SELECT t.id, t.device_code, t.device_name, t.factory_id, m.field_name AS factory_name, t.device_type, t.team_id, t.team_name, t.location, t.duty_name, t.check_emp_no, t.check_emp,t.pro_tem_check_emp_no,t.pro_tem_check_emp, t.pro_tem_begin_date,t.pro_tem_end_date, t.remark, t.create_time, t.update_emp, t.update_emp_no, t.update_time, IFNULL(cr.fault_total,0) fault_total, k.rule_id, k.rule_name, t.device_field_code, CASE WHEN t3.device_status is null then 0 WHEN t3.validate_status is null THEN 0 WHEN t3.validate_status = 1 THEN 0 ELSE IFNULL(t3.device_status,0) END device_status FROM safety_spot_check_device_info t left join safety_field_manage m on t.factory_id = m.id left join (SELECT p.spot_id, GROUP_CONCAT(r.id) AS rule_id, GROUP_CONCAT(r.rule_name) AS rule_name FROM safety_spot_check_rule r, safety_spot_rule_perm p WHERE r.id = p.rule_id GROUP BY p.spot_id) k on t.id = k.spot_id left join (SELECT device_id,sum(device_status) fault_total FROM safety_spot_check_record group by device_id) cr ON cr.device_id = t.id left join (select max(t1.device_id) device_id,max(t1.device_status) device_status,max(t1.check_time) check_time,max(t1.validate_status) validate_status,max(t1.is_reform) is_reform from safety_spot_check_record t1 where (t1.device_id,t1.check_time) in (select device_id,MAX(check_time) check_time from safety_spot_check_record where status=1 group by device_id) GROUP BY device_id) t3 on t.id = t3.device_id WHERE t.delete_falg = 0
) AS CUR_TMP WHERE 1 = 1
and device_status = #{param.deviceStatus}
ORDER BY update_time DESC limit #{start}, #{end}

SELECT * FROM ( SELECT t.id, t.device_code, t.device_name, t.factory_id, m.field_name AS factory_name, t.device_type, t.team_id, t.team_name, t.location, t.duty_name, t.check_emp_no, t.check_emp,t.pro_tem_check_emp_no,t.pro_tem_check_emp, t.pro_tem_begin_date,t.pro_tem_end_date, t.remark, t.create_time, t.update_emp, t.update_emp_no, t.update_time, IFNULL(cr.fault_total,0) fault_total, k.rule_id, k.rule_name, t.device_field_code, CASE WHEN t3.device_status is null then 0 WHEN t3.validate_status is null THEN 0 WHEN t3.validate_status = 1 THEN 0 ELSE IFNULL(t3.device_status,0) END device_status FROM safety_spot_check_device_info t left join safety_field_manage m on t.factory_id = m.id left join (SELECT p.spot_id, GROUP_CONCAT(r.id) AS rule_id, GROUP_CONCAT(r.rule_name) AS rule_name FROM safety_spot_check_rule r, safety_spot_rule_perm p WHERE r.id = p.rule_id GROUP BY p.spot_id) k on t.id = k.spot_id left join (SELECT device_id,sum(device_status) fault_total FROM safety_spot_check_record group by device_id) cr ON cr.device_id = t.id left join (select max(t1.device_id) device_id,max(t1.device_status) device_status,max(t1.check_time) check_time,max(t1.validate_status) validate_status,max(t1.is_reform) is_reform from safety_spot_check_record t1 where (t1.device_id,t1.check_time) in (select device_id,MAX(check_time) check_time from safety_spot_check_record where status=1 group by device_id) GROUP BY device_id) t3 on t.id = t3.device_id WHERE t.delete_falg = 0
) AS CUR_TMP WHERE 1 = 1
and device_status = #{param.deviceStatus}
ORDER BY update_time DESC

